from typing import Dict, Optional, Sequence, Tuple

DNA = "ACGT"

def mer(seq: Sequence[int], m: int, i: int) -> Tuple[int, ...]:
    """Length-m contiguous block starting at position i."""
    return tuple(seq[i + j] for j in range(m))

def first_repeated_mer(seq: Sequence[int], m: int) -> Optional[Tuple[int, int, Tuple[int, ...]]]:
    """First repeated m-mer (i, j, block); pigeonhole guarantees one once
    the number of windows exceeds q**m."""
    seen: Dict[Tuple[int, ...], int] = {}
    for i in range(len(seq) - m + 1):
        b = mer(seq, m, i)
        if b in seen:
            return seen[b], i, b
        seen[b] = i
    return None

if __name__ == "__main__":
    import random
    seq = [random.Random(1).randrange(4) for _ in range(260)]
    i, j, b = first_repeated_mer(seq, 4)
    print("Repeated tetramer", "".join(DNA[x] for x in b), "at", i, "and", j)
    print("Guaranteed because 4^4 = 256 < 257 windows.")

from typing import List

def de_bruijn(q: int, m: int) -> List[int]:
    """A de Bruijn sequence B(q, m): a cyclic q-ary word of length q**m in which
    every length-m block appears exactly once. Saturates the sharp bound
    N <= q**m on repeat-free windows."""
    a: List[int] = [0] * (q * m)
    out: List[int] = []
    def db(t: int, p: int) -> None:
        if t > m:
            if m % p == 0:
                out.extend(a[1:p + 1])
        else:
            a[t] = a[t - p]
            db(t + 1, p)
            for c in range(a[t - p] + 1, q):
                a[t] = c
                db(t + 1, t)
    db(1, 1)
    return out

if __name__ == "__main__":
    for q, m in [(2, 3), (4, 2), (4, 3)]:
        s = de_bruijn(q, m)
        assert len(s) == q ** m
        print(f"B({q},{m}) length {len(s)} = q^m = {q ** m}: all blocks distinct.")

import itertools
from typing import Dict, List, Optional, Tuple

def monochromatic_triangle(color: List[List[bool]]) -> Optional[Tuple[int, int, int, bool]]:
    """Fixed-vertex pigeonhole proof of R(3,3) <= 6: return a monochromatic
    triangle (a, b, d, color) for any symmetric 6x6 Boolean coloring."""
    n = len(color)
    buckets: Dict[bool, List[int]] = {True: [], False: []}
    for k in range(1, n):
        buckets[color[0][k]].append(k)
    for x, nbrs in buckets.items():
        if len(nbrs) >= 3:
            a, b, d = nbrs[0], nbrs[1], nbrs[2]
            if color[a][b] == x: return (0, a, b, x)
            if color[a][d] == x: return (0, a, d, x)
            if color[b][d] == x: return (0, b, d, x)
            return (a, b, d, not x)
    return None

if __name__ == "__main__":
    pairs = list(itertools.combinations(range(6), 2))
    all_ok = True
    for bits in range(1 << len(pairs)):
        c = [[False] * 6 for _ in range(6)]
        for idx, (i, j) in enumerate(pairs):
            v = bool((bits >> idx) & 1); c[i][j] = v; c[j][i] = v
        if monochromatic_triangle(c) is None:
            all_ok = False; break
    print("All 2^15 colorings of K_6 have a monochromatic triangle:", all_ok)

